with d as (select value r from jsonb_array_elements($q$[{"notes":["Make ahead: marinate the meat for up to 4 hours in the fridge, and caramelise the onions an hour before cooking.","The dum pukht (sealed steaming) is essential, resist the urge to open the lid. This is where the magic happens.","Some cooks add saffron soaked in warm milk to the rice before the final layer. If you have it, scatter 1 tsp saffron threads soaked in 100 ml warm milk over the meat layer.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"id":"98c52227-0c5c-4d2c-b801-20cec8b277f1"},{"notes":["Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"id":"1188e19f-42c5-4b3a-ac9d-c32c9c3d22f3"},{"notes":["The stock is the soul of this soup. If you don't have time to make your own, use a good-quality shop-bought beef stock, but warm it through gently, never let it boil hard.","Some cooks add a small handful of minced beef cooked separately; cooking it in the pot is simpler, and either way works.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"id":"347c5d46-f63c-47d6-aa3d-ef8f87db2927"},{"steps":[{"text":"Bring a pot of water to a rolling boil, until large bubbles break the surface constantly, and add the salt."},{"text":"Add the edamame and return to a boil, then cook until the pods are bright green and the beans are tender."},{"text":"Cook for 5 minutes if fresh, 4 minutes if frozen, until bright green and tender."},{"text":"Drain in a colander and cool slightly."},{"text":"Transfer to a bowl and serve. Squeeze the beans out of the pods into your mouth as you eat."}],"id":"72ac71c8-d722-4519-a549-89124c6a930b"},{"diets":["no-gluten"],"notes":["Make it a day ahead and reheat gently at 160°C for 20 minutes, the flavours marry beautifully overnight.","Short on time? Buy good passata instead of tinned tomatoes and skip the simmering step.","If you can't find fresh mozzarella, use half the quantity of low-moisture mozzarella and mix it with the parmesan.","For a vegetarian version, use a vegetarian hard cheese (made without animal rennet)."],"steps":[{"text":"Arrange eggplant slices on a clean tea towel or paper towels. Sprinkle both sides generously with salt and let sit for 15 minutes to draw out moisture. Pat dry thoroughly."},{"text":"While the eggplant rests, heat the tomato sauce: warm 2 tbsp of the oil in a large pan over medium heat. Add minced garlic and cook for 30 seconds until fragrant. Add tinned tomatoes, breaking them up with a wooden spoon. Tear in most of the basil leaves (reserve a few for garnish). Simmer for 10 minutes, stirring occasionally. Season with salt and pepper. Set aside."},{"text":"Heat the remaining oil in a large frying pan over medium-high heat. Once hot, fry eggplant slices in batches for 3–4 minutes per side until golden brown and soft. Transfer to paper towels to drain. Don't crowd the pan; let them cook in a single layer."},{"text":"Preheat the oven to 180°C."},{"text":"Spread a thin layer of tomato sauce over the base of a 23 × 33 cm baking dish. Arrange a layer of fried eggplant slices over the sauce, overlapping slightly. Top with a layer of fresh mozzarella, then a sprinkle of grated parmesan. Repeat the layers, sauce, eggplant, mozzarella, parmesan, until everything is used, ending with a good handful of parmesan on top."},{"text":"Bake uncovered for 30–35 minutes until the top is golden and bubbling at the edges. Let rest for 5 minutes before serving. Tear over the reserved fresh basil."}],"id":"95ebfa5e-0ef3-48ef-a057-fbb8b947c50b"},{"steps":[{"text":"Heat the oil in a large frying pan over medium-high heat. Add the sliced onion and cook for 2–3 minutes, stirring, until just softened."},{"text":"Add the chopped squash blossoms and a pinch of salt. Cook for 3–4 minutes, stirring gently, until the flowers have wilted and released their moisture. The mixture should be tender but not mushy. Taste and adjust salt."},{"text":"Warm the corn tortillas in a dry frying pan or directly over a gas flame for 15 seconds each, or wrap them in a damp tea towel to keep them soft."},{"text":"Divide the squash blossom filling between the tortillas, placing it on one half of each. Top the filling with pieces of cheese, then fold the tortilla in half."},{"text":"In a clean frying pan, heat a little oil over medium-high heat. Fry the quesadillas for 1–2 minutes per side until they are warmed through and the cheese begins to soften. Don't cook them so long the tortilla becomes crisp, they should stay tender."},{"text":"Serve immediately with salsa verde and a squeeze of fresh lime."}],"id":"cb66f7f2-81b7-4454-9f7f-d40785bd0b85"},{"notes":["Make it ahead: fry the rice earlier in the day and reheat gently, or serve at room temperature. Both sambals keep 2 days in the fridge.","Stretch it: add more veg sides like pickled papaya, blanched long beans or leftover roasted vegetables. Boiled egg, leftover chicken, or fried tofu work just as well as tempeh.","Food safety: Cool any leftover rice quickly and refrigerate it within an hour; reheat it until steaming hot."],"steps":[{"text":"Make sambal matah: toss the sliced shallots and chillies with lime juice and salt, then pour over the hot oil and set aside to infuse."},{"text":"Make sambal terasi: pound the chillies, shrimp paste, garlic and salt into a rough paste in a mortar, then stir through lime juice. (Or blend if you prefer it smoother.)"},{"text":"Heat the oil in a large pan over medium-high heat. Add the minced garlic and cook for 30 seconds until fragrant, then add the cooled rice, breaking up any lumps as it fries, about 5 minutes."},{"text":"Stir through the spring onions, season with salt and white pepper to taste, and remove from heat."},{"text":"Form the fried rice into small mounds on a large serving platter, each person gets 2 or 3 little portions to build on."},{"text":"Arrange the tempeh, cucumber and tomato around the rice, and put both sambals in small bowls alongside. Everyone builds their own plate, taking a mound of rice and topping it with sambal, tempeh and veg as they like."}],"id":"bb53646b-ebed-4f8a-9435-d41a6ff61e34"},{"notes":["Stockfish must be soaked in cold water for at least 4 hours (or overnight) before use, then flaked or shredded. Ask for it at West African or Asian grocers.","Make this soup in a big batch on Sunday and refrigerate for up to 3 days. Reheat gently and add a splash of water if it's thickened too much.","The okra will release plenty of slime, that's what makes the soup silky and satisfying. Stir it well as it cooks.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"steps":[{"text":"Heat the palm oil in a large pot over medium heat. Add the chopped onion and cook, stirring, until soft, about 3 minutes."},{"text":"Add the minced garlic and ginger, stir for 1 minute until fragrant."},{"text":"Stir in the tomato paste and cook for 2 minutes, breaking it down into the oil."},{"text":"Add the shredded stockfish and stir to coat. Cook for 3 minutes."},{"text":"Pour in the chicken stock and bring to a gentle simmer. Cook for 15 minutes, stirring occasionally."},{"text":"Add the sliced okra and stir well, don't worry if it looks very slimy at first. Simmer for 10 minutes."},{"text":"Add the prawns and ground crayfish if using. Simmer for another 8–10 minutes until the prawns are pink and cooked through."},{"text":"Taste and season with salt and black pepper. The soup should be thick and slippery. Serve hot over fufu."}],"id":"ec19ae6a-04a8-497a-b9d1-694848827576"},{"notes":["You can prepare the breaded chicken parcels up to 4 hours ahead and refrigerate them before frying. This helps them stay together and cook evenly.","If the oil is too hot, the coating will brown too quickly before the chicken cooks through. If it's not hot enough, the chicken will absorb oil and become greasy rather than crisp.","Serve with boiled potatoes and a simple salad of beetroot and dill, if you like.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Mix the softened butter with minced garlic, fresh dill, salt and a pinch of black pepper. Divide into 4 portions and shape each into a small block. Freeze for at least 15 minutes until firm."},{"text":"Place each chicken breast between two sheets of plastic wrap. Using a meat mallet or rolling pin, pound gently but firmly until the breast is about 5 mm thick. Work from the centre outwards, being careful not to tear the meat."},{"text":"Lay one flattened chicken breast on a clean surface. Place a butter portion in the centre. Fold the long sides over the butter, then fold in the short sides to seal, creating a neat parcel. The seam should be on the bottom."},{"text":"Place the flour on one plate, beaten eggs in a shallow bowl, and breadcrumbs on another plate. Coat each chicken parcel lightly in flour, shaking off excess. Dip in beaten egg to coat completely, then roll in breadcrumbs until fully covered. Place on a plate, seam-side down."},{"text":"Heat the oil in a large, heavy-based frying pan over medium-high heat until a breadcrumb sizzles immediately when dropped in (about 160°C)."},{"text":"Carefully place the chicken parcels seam-side up into the hot oil. Fry for 5 to 6 minutes until the breadcrumb coating is deep golden brown, then gently turn and fry the other side for another 4 to 5 minutes until crisp and the internal temperature reaches 75°C."},{"text":"Remove with a slotted spoon and drain on paper towels. Let rest for 2 minutes before serving. The butter inside will be hot, warn your family to cut carefully so they don't get splashed."}],"id":"6dde5f03-a13a-477b-8d70-20fef973cdab"},{"notes":["Stinky tofu (chou doufu) is the star here, its pungent, funky smell is what makes it special. Find it in the refrigerated section of Asian grocers, often near the fresh tofu.","The tofu needs to be truly crispy outside to contrast with the QQ creamy interior. Don't skip the cornflour coating or lower the oil temperature.","Pickled mustard greens (xue cai) cut through the richness beautifully, swap for pickled daikon if you prefer something milder."],"steps":[{"text":"Toss the stinky tofu cubes gently with cornflour and salt until coated."},{"text":"Heat about 2 cm of neutral oil in a shallow pan or wok to 180°C. Test with a wooden chopstick, it should bubble gently around it."},{"text":"Working in two batches, carefully slide the tofu into the hot oil. Fry for 4–5 minutes, turning once, until the outside is golden and crispy and the edges are bubbling. Drain on paper towels."},{"text":"While the tofu fries, stir together the chilli sauce, soy sauce, sugar and 1 tbsp water in a small bowl."},{"text":"Serve the hot tofu with pickled mustard greens on the side, the chilli sauce for dipping, and spring onion scattered over. Eat while it's still crackling."}],"id":"301ad861-b33c-4a0d-83d2-ffcc47b38917"},{"notes":["Make the sambal paste in advance (up to 2 days ahead) and store in an airtight container in the fridge. Bring it to room temperature before rubbing it on the chicken.","For less heat, use 1 or 2 chillies instead of 3. For more punch, add a bird's eye chilli or two.","Leftovers keep in an airtight container in the fridge for up to 3 days and are just as good cold the next day.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Make the sambal paste: Combine the shallots, garlic, chillies, candlenuts, tamarind paste and salt in a food processor. Pulse until you have a coarse, chunky paste, not smooth. Heat 2 tbsp neutral oil in a pan over medium heat, add the paste and fry, stirring often, for about 5 minutes until it darkens and smells fragrant. Let it cool slightly."},{"text":"Pat the chicken thighs dry with paper towel. Rub them all over with the cooled sambal paste, turmeric and coriander, working it into the skin and under it where you can. Ideally sit the chicken in a bowl for 30 minutes to an hour, but even 10 minutes helps."},{"text":"Heat about 300 ml neutral oil in a large, heavy-based pan or wok over medium-high heat. Test the heat with a small piece of shallot, it should sizzle immediately."},{"text":"Working in batches so you don't overcrowd the pan, carefully place the chicken skin-side down into the hot oil. Fry for 6–7 minutes until the skin is deep golden and crisps up, shaking the pan occasionally so it colours evenly."},{"text":"Flip each piece and fry the other side for another 6–7 minutes until golden. The chicken should be cooked through, cut into the thickest thigh near the bone and check there's no pink; if unsure, the inside should reach 75°C."},{"text":"Transfer the cooked chicken to a plate lined with paper towel to drain. Taste one piece and season with a pinch more salt if needed. Serve hot."}],"id":"ae8bc566-4d6f-440d-abef-2d2b7a80176b"},{"steps":[{"text":"Get your braai hot, you want the coals glowing and ready."},{"text":"Tear off a large piece of foil and lay the snoek in the middle. Season inside and out with salt and pepper."},{"text":"Stuff the cavity with half the garlic slices and half the lemon slices. Top with a knob of butter."},{"text":"Scatter the remaining garlic and lemon over the top, then dot with the last of the butter. Wrap the foil loosely around the fish, sealing it well so the steam stays inside, and bake until the fish is opaque and flakes easily with a fork."},{"text":"Place the parcel on the hot coals and cook for about 10 to 12 minutes, until the flesh is opaque and flaking away from the bones."},{"text":"Carefully unwrap the foil, watch the steam, and check that the fish is opaque and flakes easily. Slide the fish onto a plate. Spoon the buttery juices from the foil over the top."}],"id":"c3ec5d64-4517-40ee-aac6-ebae8eb15361"},{"notes":["Make this a day ahead if you like, it keeps well in the fridge for up to 3 days.","Lucía sometimes stirs in a splash of water to loosen it on the day if it's thickened overnight.","Serve with small glasses of ice water on the side, or pour into shallow bowls if you're feeling elegant."],"steps":[{"text":"Place the tomatoes, capsicum, cucumber and garlic in a large bowl. Pour over the olive oil and sherry vinegar, and add a pinch of salt. Let sit for 10 minutes to release the juices."},{"text":"In batches, blend the vegetables and oil until completely smooth, this is a sieve-smooth gazpacho, not a chunky one. Pass the blended mixture through a fine sieve into a clean bowl, pressing gently to extract all the liquid. Discard the pulp."},{"text":"Stir in the ice water to cool and lighten the soup. Taste and adjust the salt and vinegar to your liking."},{"text":"Cover and refrigerate for at least 2 hours, or until well chilled. Serve ice cold in small glasses or shallow bowls."}],"id":"54053b44-7952-4d3f-9750-749b514e4b3b"},{"notes":["Base genep keeps in the fridge for up to 5 days, or freeze in ice-cube trays for up to 3 months.","If you don't have fresh turmeric, use 1 tsp ground turmeric instead.","A mortar and pestle gives the best flavour and texture, but you can use a food processor if needed, pulse until smooth, then stir through the lime and salt by hand."],"id":"31791570-be7b-48e7-a97e-8153ba976bb8"},{"notes":["Use day-old or cooled cooked rice, freshly cooked rice will clump and steam instead of fry.","Shrimp paste is pungent raw but mellows when cooked with oil and the other ingredients. Start with 1 tbsp and adjust to taste.","Double this easily if you're cooking for two, but it's designed for one burner and one wok.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"id":"3cc11280-f53a-4d0f-aa45-922508bd34e1"},{"notes":["Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"139e1906-6272-436a-824b-643654998519"},{"steps":[{"text":"Preheat your camp oven with coals underneath and on top, or preheat a conventional oven to 200°C."},{"text":"In a large bowl, mix together the flour, baking powder, wattleseed and salt."},{"text":"Add the cubed butter and rub it in with your fingertips until the mixture resembles fine breadcrumbs."},{"text":"Add the warm water gradually, stirring with a knife until the dough just comes together. Don't overwork it, damper should be rough and rustic."},{"text":"Turn the dough out onto a lightly floured surface and gently shape it into a round loaf about 20 cm across. Make a shallow cross on the top with a knife."},{"text":"Place the damper on a piece of baking paper or directly on a lightly oiled cast-iron trivet in your camp oven (or on a baking tray for conventional oven)."},{"text":"Bake for 40–45 minutes until the top is golden and it sounds hollow when tapped on the base. In a camp oven, rotate the coals if needed to ensure even cooking."},{"text":"Cool on a wire rack for a few minutes, then tear into pieces and serve warm with butter."}],"id":"2b330fc3-079d-4416-ae94-2f7d1d6be214"},{"notes":["Cook the rice the night before and store in the fridge; it keeps for 3 days and is great eaten cold.","Press the tofu for 15 minutes before cutting to get it crispy, wrap it in a clean towel with a weight on top.","Swap the mango for peaches or papaya if that's what's at the farmers' market."],"id":"5fff3577-9796-44bc-9f11-a72774be05f3"},{"notes":["Make the stew up to 2 days ahead; the flavours deepen overnight. Reheat gently before serving.","Don't skip browning the kidney, it anchors the stew. If you can't find beef kidney, use lamb kidney (200 g) or omit it and add 100 g more beans instead.","Dried limes are essential to the flavour; they're sold in Middle Eastern grocers and most good supermarkets.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done. If using dried kidney beans, soak them, then boil them hard for at least 10 minutes before simmering, to destroy a natural toxin."],"id":"eeebbc70-230c-470a-9de2-16fa75d8bd13"},{"notes":["Use oil you actually like the taste of, the simplicity means quality matters. Peanut oil or a fruity olive oil both work.","Don't prep the choy sum too early; it wilts quickly. Cut and dress it just before cooking.","If your stove doesn't run hot enough to get good wok hei, finish the pan under a very hot grill for 30 seconds instead."],"steps":[{"text":"Get everything ready, the greens washed and cut, garlic bruised and sitting on the bench. High heat and speed matter here."},{"text":"Heat your wok on high until it just begins to smoke lightly, about 2 minutes. Add the oil and swirl to coat the wok surface."},{"text":"Add the bruised garlic and stir constantly for 20 seconds until fragrant. You want the oil infused but the garlic not burnt."},{"text":"Immediately add all the choy sum. Toss and stir briskly, keeping the heat high, for 2 to 3 minutes until the stems are tender and the leaves have some char at the edges. The greens should still be bright."},{"text":"Season with salt to taste. Serve immediately while the oil is still hot and the choy sum is at its best."}],"id":"51a02573-191b-47fa-a577-ae68ab84ae77"},{"notes":["The salmon can be cured up to 5 days ahead; keep it wrapped in the fridge. Slice only what you need and use the rest within a day or two.","The mustard sauce keeps refrigerated for up to 3 days.","Use the best salmon you can find, it's almost raw, so freshness matters.","The fish here is eaten raw or only cured in citrus. Buy sashimi-grade fish from a fishmonger, keep it cold and eat it the same day; skip it for anyone pregnant, very young, elderly or with low immunity.","Food safety: The seafood here is served raw or cured, so buy sashimi-grade, keep it cold and eat it the day it is made; for anyone who should avoid raw fish, cook it until opaque. Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"cf8f997a-6288-41b8-bc77-476798a51267"},{"notes":["If you can't find fresh pāua, tinned pāua from a specialist kai moana supplier works well, just drain and pound before battering.","Keep finished fritters warm in a low oven (120°C) while you fry the rest.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Pound each pāua gently but firmly with a meat mallet on both sides until soft and just starting to flatten. Don't overdo it or you'll tear them. Pat dry with paper towels."},{"text":"Whisk together the flour, baking powder, salt and pepper in a large bowl. In another bowl, whisk the egg with the milk until combined."},{"text":"Pour the wet ingredients into the dry and stir gently until just combined, the batter should be a little lumpy, not smooth."},{"text":"Heat about 2 cm of neutral oil in a large frying pan over medium-high heat until shimmering. Test with a drop of batter; it should sizzle and float."},{"text":"Dip each pāua into the batter, coating both sides, then carefully place into the hot oil. Fry in batches of 2 or 3 so you don't crowd the pan, about 2 minutes each side until golden and crispy."},{"text":"Drain on paper towels and serve hot with a squeeze of fresh lemon."}],"id":"0d54dff1-13b6-4206-8cf0-96ea38ee1cb0"},{"notes":["Make ahead: prepare the musubi the morning before and keep wrapped in the fridge. Bring to room temperature before eating, or warm gently in the microwave.","Swap the sweet soy sauce for tamari or regular soy sauce if that's what you've got, the musubi will taste less sweet but still good.","Any leftover seasoned rice can be used to make onigiri or fried rice.","Food safety: Cool any leftover rice quickly and refrigerate it within an hour; reheat it until steaming hot."],"id":"f6d16acd-ceca-43e3-9aad-e122c444b178"},{"notes":["Use veal or beef. Veal is more tender, but a thin beef cutlet works just as well.","Don't skip the meat mallet. The escalopes must be thin so they cook through before the breadcrumb coating burns.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done."],"steps":[{"text":"Make the chimichurri first: whisk together the olive oil and red wine vinegar, then stir in the parsley, oregano, garlic, chilli flakes, salt and pepper. Set aside."},{"text":"Place each veal escalope between two sheets of plastic wrap and pound with a meat mallet or rolling pin until very thin, about 3 mm. Season both sides with salt and pepper."},{"text":"Set up three shallow bowls: one with flour, one with beaten eggs, and one with breadcrumbs. Coat each escalope in flour, shaking off excess, then dip in egg, then press firmly into the breadcrumbs on both sides."},{"text":"Heat about 1 cm of neutral oil in a large frying pan over medium-high heat until it shimmers. Test with a small piece of bread, it should sizzle and brown quickly."},{"text":"Carefully lay the breaded veal into the hot oil and fry for 2–3 minutes until golden brown. Turn and fry the other side for another 2–3 minutes until crispy and golden. Do not overcrowd the pan."},{"text":"Transfer to a plate lined with paper towel to drain. Serve hot with lemon wedges and chimichurri on the side, with optional fresh parsley garnish."}],"id":"b810c302-8b19-48c5-884f-f620802c7e5b"},{"notes":["The yolk should be soft when you bite in, if you prefer it cooked through, fry for an extra minute, but you'll lose some of the magic!","If the pastry is splitting, brush the edges with a paste of flour and water to seal them better.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Set up a work station with one sheet of filo pastry in front of you, and have a small bowl of water nearby for sealing. In a small bowl, mix the drained tuna with the harissa, coriander and capers. Taste it and adjust the harissa and salt to your liking."},{"text":"Take the first filo sheet and brush it lightly with oil on both sides. Fold it in half to create a rough square."},{"text":"Spoon about 1 tbsp of the tuna mixture into the centre of the folded pastry, leaving a margin around the edges. Make a small well in the tuna mixture, then crack an egg directly into it. Season with a pinch of salt and pepper."},{"text":"Fold the pastry over the filling to create a triangle or envelope, sealing the edges by pressing firmly or brushing them with a little water. The egg should be mostly contained but might leak slightly during cooking, this is normal."},{"text":"Heat about 3 cm of oil in a deep frying pan to 180°C (or until a small piece of bread browns in about 30 seconds). Carefully place the first brik into the hot oil, seam-side down."},{"text":"Fry for 2–3 minutes, turning once halfway, until the pastry is golden and crispy on both sides. The egg inside should still have a soft yolk. Use a slotted spoon to remove it and drain on paper towels."},{"text":"Repeat with the remaining briks, making sure the oil returns to temperature between batches."},{"text":"Serve hot, on their own or with a squeeze of lemon and extra harissa on the side!"}],"id":"dbe35766-9aeb-45a4-bd02-b1981219f0bd"},{"notes":["Shorshe ilish is traditionally made during spring when hilsa is in season (March–May). If hilsa is unavailable, use fresh pomfret or mackerel, both have the oily texture this dish demands.","Prepare the mustard paste fresh; it loses its pungency if made too far ahead. The dish can be made a few hours in advance and gently reheated."],"steps":[{"text":"Soak the mustard seeds in a little water for 10 minutes, then grind to a coarse paste with the green chillies, turmeric and salt. The paste should be lumpy and pungent, not smooth."},{"text":"Heat the mustard oil in a wide, shallow pan over medium-high heat until it just smokes, about 2 minutes. This is essential, the burnt edge of the oil gives shorshe ilish its character."},{"text":"Gently lay the fish fillets skin-side up in the hot oil. Cook for 2–3 minutes without moving them, until the flesh begins to turn opaque at the edges."},{"text":"Spread the mustard paste over the fish, then add 150 ml water around (not over) it. The sauce should be loose and gravy-like."},{"text":"Bring to a simmer, then reduce heat to low. Cook, uncovered and barely disturbing the fish, for 15–18 minutes, until the flesh is cooked through and flakes easily when tested at its thickest point. The sauce should reduce and thicken slightly."},{"text":"Taste and adjust salt. Stir in the jaggery if using, a hint of sweetness balances the mustard's heat. Serve hot, with rice to soak up the sauce."}],"id":"06d61d99-cdd2-48fe-84ff-da51bdbe66e0"},{"notes":["Rendang improves overnight as the flavours marry. Make it a day ahead and gently reheat, or store in the fridge for up to 4 days.","Use a heavy-bottomed pot so the heat stays even and the sauce doesn't catch at the bottom.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"steps":[{"text":"Blend the garlic, ginger, red chillies, shallots and macadamias with 60 ml of the coconut milk until you have a smooth, thick paste. This is your spice foundation, don't rush it."},{"text":"Heat the oil in a large, heavy-bottomed pot or Dutch oven over medium heat. Add the lemongrass and bruise it gently with a wooden spoon to release its oils, about 1 minute."},{"text":"Add the spice paste and cook, stirring constantly, until it darkens and the raw smell fades, about 8–10 minutes. The paste should start to break apart and release its fragrance."},{"text":"Add the beef chunks and stir well to coat in the paste. Cook for about 5 minutes, stirring occasionally, until the beef is sealed on the outside."},{"text":"Pour in the remaining coconut milk. Stir well, then bring to a gentle simmer, until small bubbles appear at the edges. Do not boil. Reduce the heat to low."},{"text":"Simmer, uncovered, for about 60–70 minutes, stirring every 15 minutes or so. The coconut milk will gradually reduce and the sauce will thicken and darken. By the end, the beef should be very tender and the sauce should be thick and cling to the meat, not swim in liquid. This is where patience matters, watch that the heat stays gentle so the coconut doesn't split."},{"text":"Taste and season with salt. If the rendang feels too sharp, stir in the palm sugar. Remove the lemongrass stalks."},{"text":"The rendang is ready when the sauce is nearly absorbed, glossy and deep reddish-brown, and the beef is so tender it breaks easily with a spoon. Serve warm."}],"id":"6a021a39-3aa2-4e18-97bc-9f2250670ef8"},{"notes":["These are best served warm or at room temperature, not hot, the flavours settle beautifully as they cool.","You can make them a few hours ahead and reheat gently in a 150°C oven for 15 minutes.","If your tomatoes are not very ripe, add a tbsp of tomato paste to the rice mixture for more depth."],"steps":[{"text":"Cut the top off each tomato and set aside. Using a spoon, scoop out the insides, leaving about 1 cm of flesh around the walls. Chop the scooped flesh and set aside. Cut the capsicums in half and remove the seeds."},{"text":"Heat 2 tbsp of the olive oil in a large frying pan over medium heat. Cook the onion until soft, about 5 minutes. Add the garlic and cook for another minute, stirring."},{"text":"Add the rice and stir for 2 minutes to toast it lightly. Add the chopped tomato flesh, parsley, mint, oregano, and a pinch of salt and pepper. Stir well and remove from heat. Let cool slightly."},{"text":"Arrange the tomato shells and capsicum halves in a large baking dish, cut-side up. Divide the rice mixture evenly among them, pressing gently and mounding slightly, they'll settle as they cook until the rice is tender and the tops are lightly golden."},{"text":"Drizzle the remaining 2 tbsp olive oil over everything. Pour the water into the dish around (not over) the vegetables. Replace the tomato tops. Season with salt and pepper."},{"text":"Roast, uncovered, at 180°C for about 60 minutes, until the tomatoes and capsicums are very soft and the edges are slightly charred. The rice will have absorbed most of the liquid. Serve warm or at room temperature."}],"id":"cd5139ba-651e-4292-8e06-f67c887dc10f"},{"notes":["This keeps well in an airtight container in the fridge for up to 5 days, making it perfect for bento prep.","If you can't find burdock, use parsnip cut into thin matchsticks; it cooks a little faster but has a similar sweetness.","Hijiki expands as it soaks, so don't skip that step, the texture will be much better."],"id":"7a434c40-e813-499c-9bc6-28b5e6cca24b"},{"steps":[{"text":"Chop the tomatoes, cucumber and red onion into roughly the same size pieces. Put them in a big bowl."},{"text":"Add the olive oil, lemon juice and oregano. Toss everything together and season with salt and pepper."},{"text":"Let it sit for 2 minutes, until the salt has drawn out a little juice and the vegetables are glossy, so the flavours come together."},{"text":"Scatter the feta on top and toss through gently. Serve straight away."}],"id":"1050cc3f-5e37-4012-a32d-1732d574211b"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;